PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS profiles (user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, data TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS attempts (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, activity_id TEXT NOT NULL, skill TEXT NOT NULL, mode TEXT NOT NULL, day INTEGER, started_at TEXT NOT NULL, deadline TEXT, submitted_at TEXT, answers TEXT NOT NULL DEFAULT '{}', snapshot TEXT NOT NULL, result TEXT, active_seconds INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS attempts_user ON attempts(user_id, submitted_at);
CREATE TABLE IF NOT EXISTS mistakes (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, question_id TEXT NOT NULL, activity_id TEXT NOT NULL, question TEXT NOT NULL, answer TEXT NOT NULL, correction TEXT NOT NULL, explanation TEXT NOT NULL, category TEXT NOT NULL, repetitions INTEGER NOT NULL DEFAULT 1, status TEXT NOT NULL DEFAULT 'Learning', due TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(user_id, activity_id, question_id));
CREATE TABLE IF NOT EXISTS vocabulary_reviews (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, word_id TEXT NOT NULL, interval_days INTEGER NOT NULL DEFAULT 0, due TEXT NOT NULL, reviews INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(user_id, word_id));
CREATE TABLE IF NOT EXISTS study_days (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, day INTEGER NOT NULL, reflection TEXT NOT NULL, completed_at TEXT NOT NULL, PRIMARY KEY(user_id, day));
CREATE TABLE IF NOT EXISTS writing (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, prompt_id TEXT NOT NULL, day INTEGER, body TEXT NOT NULL, submitted_at TEXT, feedback TEXT, updated_at TEXT NOT NULL, UNIQUE(user_id, prompt_id));
CREATE TABLE IF NOT EXISTS recordings (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, prompt TEXT NOT NULL, mime TEXT NOT NULL, file TEXT NOT NULL, transcript TEXT NOT NULL DEFAULT '', duration INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tutor_messages (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, role TEXT NOT NULL, body TEXT NOT NULL, created_at TEXT NOT NULL);
